#include <iostream>
#define MOD 1000000007LL
using namespace std;

long long fast_pow(int base, int exp);

int main() {
    long long p, k, q;
    cin >> p >> k;
    q = k;
    if (k == 0) {
        cout << fast_pow(p, p - 1);
        return 0;
    } else if (k == 1) {
        cout << fast_pow(p, p);
        return 0;
    }
    int cycle_count = 1;
    while (q != 1) {
        q = (q * k) % p;
        cycle_count++;
    }
    cout << fast_pow(p, (p - 1) / cycle_count);
    return 0;
}

long long fast_pow(int base, int power) {
    long long result = 1;
    long long current = base;
    long long pwr = power;
    while (pwr > 0) {
        if (pwr & 1) {
            result = (result * current) % MOD;
        }
        current = (current * current) % MOD;
        pwr >>= 1;
    }
    return result;
}
